def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find a solid separator row or column.
    sep = None
    for r in range(h):
        if len(set(grid[r])) == 1:
            sep = ('h', r, grid[r][0])
            break
    if sep is None:
        for c in range(w):
            if len({grid[r][c] for r in range(h)}) == 1:
                sep = ('v', c, grid[0][c])
                break

    if sep:
        axis, k, _ = sep
        if axis == 'h':
            a, b = grid[:k], grid[k+1:]
            # Usually encode the region with more variation; if the far side
            # is a uniform field, encode the nonuniform side.
            def variety(part):
                return sum(x != part[0][0] for row in part for x in row)
            if not b or variety(a) >= variety(b):
                target, reference = a, b
            else:
                target, reference = b, a
            ref_counts = {}
            for row in reference:
                for x in row:
                    ref_counts[x] = ref_counts.get(x, 0) + 1
        else:
            a = [row[:k] for row in grid]
            b = [row[k+1:] for row in grid]
            target, reference = b, a
            ref_counts = {}
            for row in reference:
                for x in row:
                    ref_counts[x] = ref_counts.get(x, 0) + 1
    else:
        # Fallback for a two-part pattern without a full separator.
        target = grid[h//2:]
        reference = grid[:h//2]
        ref_counts = {}
        for row in reference:
            for x in row:
                ref_counts[x] = ref_counts.get(x, 0) + 1

    if not target or not target[0]:
        return [[0]]
    base = max(ref_counts, key=ref_counts.get) if ref_counts else target[0][0]
    counts = {}
    for row in target:
        for x in row:
            counts[x] = counts.get(x, 0) + 1
    rare = min(counts, key=counts.get)
    return [[3 if x == rare else base for x in row] for row in target]
