    # Locate the solid divider between two same-sized panels.
    for c in range(w):
        if all(grid[r][c] == grid[0][c] for r in range(h)):
            left = [row[:c] for row in grid]
            right = [row[c+1:] for row in grid]
            if left and right and len(left[0]) == len(right[0]):
                a, b = left, right
                break
    else:
        for r in range(h):
            if len(set(grid[r])) == 1:
                top, bottom = grid[:r], grid[r+1:]
                if top and bottom and len(top) == len(bottom):
                    a, b = top, bottom
                    break
        else:
            return [row[:] for row in grid]

    matches = {}
    for i in range(len(a)):
        for j in range(len(a[0])):
            if a[i][j] == b[i][j]:
                v = a[i][j]
                matches[v] = matches.get(v, 0) + 1
    background = max(matches, key=matches.get) if matches else 0
    return [
        [3 if a[i][j] == b[i][j] == background else background
         for j in range(len(a[0]))]
        for i in range(len(a))
    ]
